const paths={home:'M3 10 12 3l9 7M5 9v12h5v-7h4v7h5V9',grid:'M3 3h7v7H3zM14 3h7v7h-7zM3 14h7v7H3zM14 14h7v7h-7z',file:'M14 2H5v20h14V7l-5-5ZM14 2v6h5M8 12h8M8 16h8',chevron:'m9 5 7 7-7 7',down:'m6 9 6 6 6-6',calendar:'M4 5h16v16H4zM8 2v6M16 2v6M4 11h16',check:'m3 12 5 5L20 5m-8 12 9-9',alert:'m12 3 10 18H2L12 3Zm0 6v5m0 3h.01',clock:'M12 8v5l3 2M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',arrow:'M6 18 18 6M6 6h12v12',reset:'M3 10a9 9 0 1 1 1 8M3 3v7h7',search:'M21 21l-5-5M18 10a8 8 0 1 1-16 0 8 8 0 0 1 16 0',eye:'M2 12s4-7 10-7 10 7 10 7-4 7-10 7S2 12 2 12Zm13 0a3 3 0 1 1-6 0 3 3 0 0 1 6 0',back:'m12 5-7 7 7 7M5 12h15',close:'m6 6 12 12M6 18 18 6',users:'M16 21v-3a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v3M13 6a4 4 0 1 1-8 0 4 4 0 0 1 8 0M17 3a4 4 0 0 1 0 8M22 21v-3a4 4 0 0 0-3-4'};
const icon=n=>`<svg viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[n]||paths.file}"/></svg>`;
const statuses=['Draf','Perlu perbaikan','Menunggu pemeriksaan','Menunggu verifikasi','Menunggu persetujuan','Disetujui'];
const colors=['#8a99ad','#ed8344','#9b7bcb','#5397d7','#d5ae40','#128977'];
const regions=[['Kab. Kotawaringin Barat','Desa Kumpai Batu Atas','Andreas Maleh'],['Kab. Kotawaringin Barat','Desa Pasir Panjang','Sisca Enjelina'],['Kab. Kapuas','Desa Pulau Telo','Dedi Irawan'],['Kota Palangka Raya','Kel. Bukit Tunggal','Rina Anggraini'],['Kab. Katingan','Desa Hampalit','Agus Setiawan'],['Kab. Pulang Pisau','Desa Mantaren I','Lina Marlina']];
const names=['Marnon','Siti Aminah','Suharto','Jumilah','Ahmad Yani','Sri Wahyuni','Bambang Sugianto','Dewi Lestari','Herman','Rukmini','Junaidi','Nursiah','Slamet Riyadi','Yuliana','Rahmat Hidayat','Rusmini','Suryadi','Mardiana','Abdul Rahman','Hartini','Sutrisno','Rosdiana','Muhammad Yusuf','Ratnawati','Darmadi','Nurhayati','Sukardi','Sulastri','Iskandar','Lilis Suryani','Hendra','Mariam','Suranto','Sarinah','Budi Santoso','Ernawati'];
const data=names.map((name,i)=>({id:String(62040018+i),name,nik:'6204••••••••'+String(1001+i),gender:i%2?'Perempuan':'Laki-laki',region:regions[i%6][0],village:regions[i%6][1],fac:regions[i%6][2],address:`Jl. ${['Tjilik Riwut','Meranti','Pembangunan','Cempaka','Merdeka','Melati'][i%6]} No. ${12+i}, RT 00${i%5+1}`,status:statuses[[5,1,3,0,4,2,0,1,5][i%9]],progress:[100,67,83,33,100,83,17,50,100][i%9]}));
let state={region:'',village:'',fac:'',status:'',tab:'BNBA',query:'',page:1};
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const filtered=()=>data.filter(d=>(!state.region||d.region===state.region)&&(!state.village||d.village===state.village)&&(!state.fac||d.fac===state.fac)&&(!state.status||d.status===state.status));
const badge=s=>`<span class="badge" style="background:${colors[statuses.indexOf(s)]}18;color:${['#62758b','#b65a27','#7e5db0','#3376ae','#97761a','#087a68'][statuses.indexOf(s)]}">${s}</span>`;
function shell(content,detail=false){return `<header class="topbar"><a class="brand-icon" href="#" aria-label="Dashboard RAB">${icon('home')}</a><a href="#" class="brand">Bedah Rumah <span style="color:var(--teal)">Kalteng</span><small>PEMERINTAH PROVINSI KALIMANTAN TENGAH</small></a><nav class="toplinks" aria-label="Navigasi utama"><a href="#" class="${!detail?'active':''}">${icon('grid')} Dashboard RAB</a><a href="#rekap" class="${detail?'active':''}">${icon('file')} Rekap & Detail RAB</a></nav><div class="user"><div class="avatar">AD</div><div>Administrator<small>Pengelola program</small></div></div></header><main class="container">${content}<footer class="footer"><span>© 2026 · RAB Bedah Rumah Kalteng</span><span>Program bantuan perumahan · Kalimantan Tengah</span></footer></main>`}
function selector(key,label,all,values){return `<div><label for="${key}">${label}</label><select id="${key}" data-filter="${key}"><option value="">${all}</option>${[...new Set(values)].map(v=>`<option ${state[key]===v?'selected':''} value="${esc(v)}">${v}</option>`).join('')}</select></div>`}
function dashboard(){const rows=filtered(),count=s=>rows.filter(r=>r.status===s).length,completed=count('Disetujui'),pct=rows.length?Math.round(rows.reduce((a,r)=>a+r.progress,0)/rows.length):0;document.getElementById('app').innerHTML=shell(`<div class="crumb">${icon('home')}<span>Beranda</span>${icon('chevron')}<span>Dashboard RAB</span></div><div class="heading"><div><div class="eyebrow">MONITORING BANTUAN PERUMAHAN</div><h1>Progres RAB<span>.</span></h1><p>Pantau penyusunan RAB, dari draf hingga disetujui.</p></div><div class="period">${icon('calendar')}<span><small>Tahun anggaran</small> <b>2026</b></span></div></div><div class="source"><span><i class="dot"></i> Data sumber · <strong>Data contoh program Bedah Rumah</strong></span><span>${data.length} BNBA · ${new Set(data.map(d=>d.region)).size} kabupaten/kota · ${new Set(data.map(d=>d.fac)).size} fasilitator</span></div><section class="filters" aria-label="Filter RAB">${selector('region','Kabupaten/kota','Semua kabupaten/kota',data.map(d=>d.region))}${selector('village','Desa/kelurahan','Semua desa/kelurahan',data.filter(d=>!state.region||d.region===state.region).map(d=>d.village))}${selector('fac','Fasilitator','Semua fasilitator',data.filter(d=>(!state.region||d.region===state.region)&&(!state.village||d.village===state.village)).map(d=>d.fac))}${selector('status','Status RAB','Semua status',statuses)}<button class="reset" id="reset" title="Reset filter" aria-label="Reset filter">${icon('reset')}</button></section><section class="stats" aria-label="Ringkasan RAB">${[['Total RAB',rows.length,'No. BNBA unik dalam pilihan','file'],['Disetujui',completed,'Penyusunan RAB selesai','check'],['Perlu perbaikan',count('Perlu perbaikan'),'Perlu tindak lanjut fasilitator','alert'],['Terkirim',count('Menunggu pemeriksaan'),'Menunggu pemeriksaan','arrow'],['Dalam pemeriksaan',count('Menunggu verifikasi')+count('Menunggu persetujuan'),'Menunggu verifikasi & persetujuan','clock']].map(([title,value,desc,ico],i)=>`<div class="stat"><div class="stat-top">${title}${icon(ico)}</div><div class="value">${value}${i===1?`<span class="tag">${rows.length?(completed/rows.length*100).toFixed(1).replace('.',','):0}%</span>`:''}</div><p>${desc}</p></div>`).join('')}</section><section class="charts"><div class="panel distribution"><div class="panel-title"><strong>Sebaran status RAB</strong><small>${rows.length} BNBA</small></div><div class="stack" aria-label="Sebaran status RAB">${statuses.map((s,i)=>count(s)?`<div style="width:${count(s)/rows.length*100}%;background:${colors[i]}" title="${s}: ${count(s)}"></div>`:'').join('')}</div><div class="legend">${statuses.map((s,i)=>`<div class="legend-item"><i style="background:${colors[i]}"></i>${s}<b>${count(s)}</b></div>`).join('')}</div></div><div class="panel completion"><div class="eyebrow">KELENGKAPAN DOKUMEN</div><div class="value">${pct}<small>%</small></div><div class="progress"><i style="width:${pct}%"></i></div><p>Rata-rata kelengkapan dokumen.<br>Dokumen lengkap belum tentu disetujui.</p></div></section><section id="rekap"><div class="section-heading"><div><h2>Rekap & Detail RAB</h2><p>Telusuri wilayah, fasilitator, dan penerima bantuan.</p></div><span class="pill">Data contoh</span></div><div class="panel"><div class="table-toolbar"><div class="tabs" role="tablist" aria-label="Kelompok rekap">${['Kabupaten/kota','Desa/kelurahan','Fasilitator','BNBA'].map(t=>`<button role="tab" aria-selected="${t===state.tab}" data-tab="${t}" class="${t===state.tab?'active':''}">${t==='BNBA'?'Daftar BNBA':t}${t==='BNBA'?`<span class="menu-count">${rows.length}</span>`:''}</button>`).join('')}</div><div class="search">${icon('search')}<input id="search" type="search" aria-label="Cari data" placeholder="${state.tab==='BNBA'?'Cari nama, NIK, atau no. BNBA…':'Cari '+state.tab.toLowerCase()+'…'}" value="${esc(state.query)}"></div></div><div id="table-area"></div></div></section>`);renderTable();document.querySelectorAll('[data-filter]').forEach(el=>el.onchange=()=>{state[el.dataset.filter]=el.value;if(el.dataset.filter==='region'){state.village='';state.fac=''}if(el.dataset.filter==='village')state.fac='';state.page=1;dashboard()});document.getElementById('reset').onclick=()=>{state={region:'',village:'',fac:'',status:'',tab:'BNBA',query:'',page:1};dashboard()};document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{state.tab=b.dataset.tab;state.query='';state.page=1;dashboard()});document.getElementById('search').oninput=e=>{state.query=e.target.value;state.page=1;renderTable()}}
function renderTable(){let rows=filtered();const isBNBA=state.tab==='BNBA',keys={'Kabupaten/kota':'region','Desa/kelurahan':'village',Fasilitator:'fac'},key=keys[state.tab];let list=isBNBA?rows.filter(r=>[r.id,r.name,r.nik,r.address,r.region,r.village,r.fac].join(' ').toLowerCase().includes(state.query.toLowerCase())):[...new Set(rows.map(r=>r[key]))].filter(v=>v.toLowerCase().includes(state.query.toLowerCase())).map(name=>({name,rows:rows.filter(r=>r[key]===name)}));let total=list.length,pages=Math.max(1,Math.ceil(total/6));state.page=Math.min(state.page,pages);const slice=list.slice((state.page-1)*6,state.page*6);document.getElementById('table-area').innerHTML=`<div class="table-scroll"><table><thead><tr>${(isBNBA?['No. BNBA / Nama','NIK','Jenis kelamin','Wilayah','Alamat','Fasilitator','Status','']:['No.',state.tab,'Jumlah BNBA','Disetujui','Kelengkapan','']).map(t=>`<th scope="col">${t}</th>`).join('')}</tr></thead><tbody>${slice.map((r,i)=>isBNBA?`<tr><td><div class="person"><div class="avatar">${r.name.split(' ').map(n=>n[0]).slice(0,2).join('')}</div><div><a href="#bnba/${r.id}">${r.name}</a><small>${r.id}</small></div></div></td><td>${r.nik}</td><td>${r.gender}</td><td>${r.region}<small>${r.village}</small></td><td>${r.address.split(',')[0]}<small>${r.address.split(',')[1]}</small></td><td>${r.fac}</td><td>${badge(r.status)}</td><td><a class="row-arrow" href="#bnba/${r.id}" aria-label="Detail ${r.name}">${icon('chevron')}</a></td></tr>`:`<tr><td>${(state.page-1)*6+i+1}</td><td><a href="#rekap" data-group="${esc(r.name)}"><b>${r.name}</b></a></td><td>${r.rows.length} BNBA</td><td>${r.rows.filter(d=>d.status==='Disetujui').length}</td><td>${Math.round(r.rows.reduce((a,d)=>a+d.progress,0)/r.rows.length)}%</td><td><button class="view" data-group="${esc(r.name)}">${state.tab==='Fasilitator'?'Lihat BNBA':'Lihat detail'}${icon('chevron')}</button></td></tr>`).join('')||`<tr><td colspan="8" class="empty">Tidak ada data yang sesuai. Ubah pencarian atau reset filter.</td></tr>`}</tbody></table></div><div class="pagination"><span>Menampilkan ${total?(state.page-1)*6+1:0}–${Math.min(state.page*6,total)} dari ${total} ${isBNBA?'BNBA':'data'}</span><div class="pages"><button data-page="${state.page-1}" ${state.page===1?'disabled':''} aria-label="Halaman sebelumnya">‹</button>${Array.from({length:pages},(_,i)=>`<button data-page="${i+1}" class="${state.page===i+1?'active':''}" aria-label="Halaman ${i+1}" ${state.page===i+1?'aria-current="page"':''}>${i+1}</button>`).join('')}<button data-page="${state.page+1}" ${state.page===pages?'disabled':''} aria-label="Halaman berikutnya">›</button></div></div>`;document.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>{state.page=Number(b.dataset.page);renderTable()});document.querySelectorAll('[data-group]').forEach(b=>b.onclick=e=>{e.preventDefault();state[key]=b.dataset.group;state.tab={'Kabupaten/kota':'Desa/kelurahan','Desa/kelurahan':'Fasilitator',Fasilitator:'BNBA'}[state.tab];state.query='';state.page=1;dashboard();document.getElementById('rekap').scrollIntoView({block:'start',behavior:'smooth'})})}
const docNames=['Lembar Verifikasi Calon Penerima Bantuan','Rencana Anggaran Biaya (RAB)'];
function detail(id){const r=data.find(d=>d.id===id);if(!r){location.hash='';return}document.getElementById('app').innerHTML=shell(`<div class="crumb"><a href="#">${icon('home')}</a><a href="#rekap">Rekap & Detail RAB</a>${icon('chevron')}<span>${r.name}</span></div><a class="back" href="#rekap" style="display:inline-flex;align-items:center;gap:8px">${icon('back')} Kembali ke daftar BNBA</a><div class="section-heading"><div><div class="eyebrow">PENERIMA BANTUAN</div><h2>Detail BNBA</h2></div><span class="pill">Data contoh</span></div><section class="panel detail-header"><div><div class="chips"><span>TAHUN 2026</span><span>TAHAP 2</span></div><h1>${r.name.toUpperCase()}</h1><p>NIK ${r.nik} <span style="color:#ccd7df;padding:0 10px">|</span> No. BNBA <b>${r.id}</b></p></div><div class="fac"><small>FASILITATOR VERIFIKASI</small><div><b>1. ${r.fac.toUpperCase()}</b> (T)</div><div>2. ${r.fac==='Sisca Enjelina'?'ANDREAS MALEH':'SISCA ENJELINA'} (P)</div></div></section><div class="detail-grid"><aside class="panel info"><h2>Informasi penerima</h2><dl>${[['No. BNBA',r.id],['Nama lengkap',r.name],['NIK',r.nik],['Jenis kelamin',r.gender],['Kabupaten/kota',r.region],['Desa/kelurahan',r.village],['Alamat',r.address],['Fasilitator',r.fac],['Status RAB',badge(r.status)]].map(([k,v])=>`<dt>${k}</dt><dd>${v}</dd>`).join('')}</dl></aside><div><section class="panel docs"><h2>Informasi surat</h2><div class="letters">${['Surat Instruksi Verifikasi','Berita Acara Verifikasi','Penetapan CPB','Penetapan PB'].map((s,i)=>`<article class="letter">${icon('file')}<strong>${s}</strong><p>${i<2?'Belum ada surat terlampir':'Belum ada dokumen penetapan'}</p></article>`).join('')}</div></section><section class="panel docs"><div class="panel-title"><h2 style="margin:0">Penyusunan RAB</h2><span class="pill">2 jenis dokumen</span></div><table class="document-table"><thead><tr><th style="width:45px">No.</th><th>Jenis dokumen</th><th style="width:100px">File</th></tr></thead><tbody>${docNames.map((n,i)=>`<tr><td>${i+1}</td><td><b>${n}</b><small>Pratinjau awal</small></td><td><button class="view" data-doc="${i}">${icon('eye')} Lihat</button></td></tr>`).join('')}</tbody></table><div class="notice">Pengisian dan ekspor dokumen akan tersedia pada tahap pengembangan berikutnya.</div></section></div></div>`,true);document.querySelectorAll('[data-doc]').forEach(b=>b.onclick=()=>openDoc(r,Number(b.dataset.doc)))}
function openDoc(r,i){const dialog=document.getElementById('document');document.getElementById('doc-content').innerHTML=`<div class="modal-head"><div><div class="eyebrow">PRATINJAU DOKUMEN</div><h2>${docNames[i]}</h2></div><button id="close-doc" aria-label="Tutup pratinjau">${icon('close')}</button></div><div class="modal-body"><div class="paper"><div class="eyebrow">PROGRAM BEDAH RUMAH · KALIMANTAN TENGAH</div><h3>${docNames[i].toUpperCase()}<br>TAHUN ANGGARAN 2026</h3><dl>${[['No. BNBA',r.id],['Nama penerima',r.name],['NIK',r.nik],['Wilayah',r.region+' / '+r.village],['Alamat',r.address],['Fasilitator',r.fac]].map(([k,v])=>`<dt>${k}</dt><dd>${v}</dd>`).join('')}</dl><div class="notice">${i===0?'Rincian verifikasi calon penerima bantuan':'Rincian pekerjaan, volume, dan biaya'} belum diisi. Formulir dan ekspor dokumen akan dikembangkan pada tahap berikutnya.</div></div></div><div class="modal-foot"><button id="done-doc">Tutup pratinjau</button></div>`;document.getElementById('close-doc').onclick=()=>dialog.close();document.getElementById('done-doc').onclick=()=>dialog.close();dialog.showModal()}
function route(){const m=location.hash.match(/^#bnba\/(\d+)$/);if(m){detail(m[1]);window.scrollTo(0,0)}else{dashboard();if(location.hash==='#rekap')document.getElementById('rekap').scrollIntoView();else window.scrollTo(0,0)}}window.addEventListener('hashchange',route);route();
